package com.bank.salary;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class DoubleStreamDemo {
    private static final Logger log = Logger.getLogger("Salary");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> team = List.of(
            new Employee("Rajesh", new BigDecimal("1000000")),
            new Employee("Priya", new BigDecimal("250000")));
        SalaryStatsService service = new SalaryStatsService();

        log.info(() -> "Avg (team)  = " + service.averageSalary(team));
        log.info(() -> "Avg (empty) = " + service.averageSalary(List.of()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
    Employee(String name, BigDecimal salary) { this.name = name; this.salary = salary; }
    double getSalaryAsDouble() { return salary.doubleValue(); }
}

// ─── Would be in service/SalaryStatsService.java ───
class SalaryStatsService {
    double averageSalary(List<Employee> team) {
        return team.stream()
            .mapToDouble(Employee::getSalaryAsDouble)  // Stream → DoubleStream
            .average()                                  // OptionalDouble
            .orElse(0.0);                               // empty team → 0.0
    }
}
